    bool isPossible(vector<int>& target) {
        priority_queue<int> pq;
        long long int sum=0;
        for(auto it:target)
        {
            sum+=it;
            pq.push(it);
        }
        while(pq.top()!=1)
        {
            int val=pq.top();
            pq.pop();
            sum-=val;
            if(val<=sum or sum<1)
                return false;
            val%=sum;
            sum+=val;
            if(val)
